function scalar(value: unknown, source: string, offset: number): string {
  if (value == null) return "";
  switch (typeof value) {
    case "string":
      return value;
    case "number":
    case "bigint":
    case "boolean":
      return String(value);
    default:
      throw new Error(`Cannot render ${typeof value} as scalar text at ${position(source, offset)}`);
  }
